import { CliError } from './errors.js'

const NAME_PATTERN = /^[A-Za-z0-9_-]+$/
const COUNT_PATTERN = /^[1-9][0-9]*$/

/**
 * @param {string} input the raw standard input text
 * @returns {{ candidates: string[], ballots: { count: bigint, names: string[] }[] }}
 */
export function parseElection(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  let candidates = null
  const candidateSet = new Set()
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]
    const rest = tokens.slice(1)

    if (directive === 'candidates') {
      if (candidates !== null) {
        throw new CliError('candidates must be declared once, before any ballot', lineNumber)
      }
      if (rest.length === 0) {
        throw new CliError('expected candidates <name>...', lineNumber)
      }
      for (const name of rest) {
        if (!NAME_PATTERN.test(name)) {
          throw new CliError(`invalid candidate name ${name}`, lineNumber)
        }
        if (candidateSet.has(name)) {
          throw new CliError(`candidate ${name} is declared twice`, lineNumber)
        }
        candidateSet.add(name)
      }
      candidates = rest.slice()
    } else if (directive === 'ballot') {
      if (candidates === null) {
        throw new CliError('candidates must be declared once, before any ballot', lineNumber)
      }
      if (rest.length < 2) {
        throw new CliError('expected ballot <count> <candidate>...', lineNumber)
      }
      const [countToken, ...names] = rest
      if (!COUNT_PATTERN.test(countToken)) {
        throw new CliError('count must be a positive integer', lineNumber)
      }
      const seen = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          throw new CliError(`unknown candidate ${name}`, lineNumber)
        }
        if (seen.has(name)) {
          throw new CliError(`candidate ${name} is repeated`, lineNumber)
        }
        seen.add(name)
      }
      ballots.push({ count: BigInt(countToken), names })
    } else {
      throw new CliError(`unknown directive ${directive}`, lineNumber)
    }
  }

  if (candidates === null) {
    throw new CliError('no candidates')
  }

  return { candidates, ballots }
}
"}

