 * Runs the instant-runoff count described by the specification: repeatedly
 * tally the ballots for the candidates still continuing, stop with a winner
 * or with no winner, and otherwise eliminate the candidate with the fewest
 * votes, breaking ties by comparing full round-by-round vote histories and
 * finally by name.
 */

/**
 * @param {{ candidates: string[], ballots: { count: bigint, names: string[] }[] }} election
 * @returns {{
 *   rounds: { votes: Map<string, bigint>, exhausted: bigint, eliminated: string | null }[],
 *   winner: string | null,
 * }}
 */
export function runElection(election) {
  const continuing = new Set(election.candidates)
  const history = []
  const rounds = []
  let winner = null

  for (;;) {
    const votes = new Map()
    for (const name of continuing) votes.set(name, 0n)
    let exhausted = 0n

    for (const ballot of election.ballots) {
      const choice = ballot.names.find((name) => continuing.has(name))
      if (choice === undefined) {
        exhausted += ballot.count
      } else {
        votes.set(choice, votes.get(choice) + ballot.count)
      }
    }

    history.push(votes)

    let activeTotal = 0n
    for (const v of votes.values()) activeTotal += v

    let roundWinner = null
    if (activeTotal > 0n) {
      for (const [name, count] of votes) {
        if (count * 2n > activeTotal) {
          roundWinner = name
          break
        }
      }
    }

    if (roundWinner !== null) {
      rounds.push({ votes, exhausted, eliminated: null })
      winner = roundWinner
      break
    }

    if (activeTotal === 0n) {
      rounds.push({ votes, exhausted, eliminated: null })
      break
    }

    const eliminated = chooseElimination(continuing, votes, history)
    rounds.push({ votes, exhausted, eliminated })
    continuing.delete(eliminated)
  }

  return { rounds, winner }
}

function chooseElimination(continuing, votes, history) {
  let fewest = null
  for (const name of continuing) {
    const count = votes.get(name)
    if (fewest === null || count < fewest) fewest = count
  }
  let tied = [...continuing].filter((name) => votes.get(name) === fewest)

  while (tied.length > 1) {
    let distinguished = false
    for (const roundVotes of history) {
      const at = tied.map((name) => roundVotes.get(name))
      const min = at.reduce((a, b) => (b < a ? b : a))
      if (at.some((v) => v !== min)) {
        tied = tied.filter((name) => roundVotes.get(name) === min)
        distinguished = true
        break
      }
    }
    if (!distinguished) break
  }

  if (tied.length === 1) return tied[0]
  return tied.slice().sort().pop()
}
"}

