/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { CliError } from './errors.js'
import { parseElection } from './parse.js'
import { runElection } from './count.js'
import { formatRounds, formatTally } from './format.js'

function readStdin() {
  return new Promise((resolve, reject) => {
    const chunks = []
    process.stdin.on('data', (chunk) => chunks.push(chunk))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

async function main() {
  const mode = process.argv[2]
  if (mode !== 'rounds' && mode !== 'tally') {
    process.stderr.write('error: usage: cli.js rounds|tally\n')
    process.exit(2)
    return
  }

  const input = await readStdin()

  let election
  try {
    election = parseElection(input)
  } catch (error) {
    if (error instanceof CliError) {
      process.stderr.write(error.toDiagnostic() + '\n')
      process.exit(2)
      return
    }
    throw error
  }

  const result = runElection(election)
  process.stdout.write(mode === 'rounds' ? formatRounds(result) : formatTally(result))
}

main()
"}

